LABELS={'A':'Baseline LNS control','B':'Historical pattern transfer','C':'Learned transfer ranking','D':'Composed transformations','E':'Hybrid structural synthesis','P':'Pure Cell-First motif transfer'}

def category(label):
    if label.startswith('transfer_op4'):return 'P'
    if label.startswith(('transfer_op','Historical')):return 'B'
    if label.startswith('Hybrid'):return 'E'
    return label[0]

